# -*- coding: utf-8 --

from taf.rfrl.cbts.connections.ssh_connections import SSHConnExec
from taf.rfrl.cbts.parsers.parsers import parse_output_with_ps_format_to_dict


class VDUCli(SSHConnExec):
    def get_vdu_pod_info(self, namespace, alias='default'):
        """
        Get vdu all pod information via command kubectl get pods -o wide
        :param str alias: vdu ssh connection alias
        :return: dict pod informaiton: including age, ip, name, node, nominated_node, readiness_gates, ready, restarts, status
        """

        command = 'kubectl get pods -n %s -o wide' % namespace
        output = SSHConnExec.execute_normal_cmd(self, base_command=command, alias=alias)
        return parse_output_with_ps_format_to_dict(output)

    def get_vdu_pod_container_mapping_info(self, pod_info, namespace, alias='default'):
        """
        Get vdu all pod and container mapping via command kubectl get describe pod ...
        :param dict pod_info: the pod information get from get_vdu_pod_info
        :param str namespce: namespace get from testline _init_.py
        :param str alias: vdu ssh connection alias
        :return: dict vdu pod container mapping: {[pod_name: container_1, container_2,...]}
        """
        pod_container_mapping = {}
        for pod in pod_info:
            containers = []
            command = \
                'kubectl describe pod ' + pod + '| grep -B 1 \'Container ID\' | grep -v \'Container ID\\|--\' | awk \'{print $0}\''
            output = SSHConnExec.execute_normal_cmd(self, base_command=command, alias=alias)
            for line in output.splitlines():
                line = line.strip(':').strip()
                containers.append(line)
            pod_container_mapping[pod] = containers
        return pod_container_mapping

    def get_all_pods_name_of_one_certain_type(self, ns, pod_abbr, alias='default'):
        all_pods_info = self.get_vdu_pod_info(namespace=ns, alias=alias)
        return [pod_name for pod_name in all_pods_info.keys() if pod_abbr in pod_name]

    def execute_vdu_pod_restart_by_killing_process(self, pod_name, container_name, namespace,
                                                   process_name='ministarter', conn_alias='default'):
        kill_process_cmd = 'pkill {}'.format(process_name)
        output = self.execute_kubectl_exec_cmd(pod_name=pod_name,
                                               container_name=container_name,
                                               namespace=namespace,
                                               command=kill_process_cmd,
                                               conn_alias=conn_alias)
        return output

    def vdu_get_container_id(self, pod_name, container_name, alias, namespace):
        pod_full_name, container_full_name = self.get_full_pod_and_container_name(pod_abbr=pod_name, namespace=namespace,
                                                                                  container_abbr=container_name, alias=alias)
        out = self.execute_normal_cmd(
            base_command='kubectl describe pods %s' % pod_full_name, namespace=namespace,
            pipe_cmd="""| grep "%s:" -A 1 |grep -i "container id"|awk -F "//" '{print $2}'""" % container_full_name,
            alias=alias)
        container_id = out.strip()
        return container_id
